package com.trainflow.pricing; import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import com.trainflow.shared.error.ApiError;import com.trainflow.program.*;import com.trainflow.trainingcase.*;import java.math.BigDecimal;import java.util.*;import org.junit.jupiter.api.*;import org.mockito.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;
class PricingServiceTest{@Mock TrainingPricingRepository pricings;@Mock TrainingCaseRepository cases;@Mock TrainingProgramRepository programs;@Mock ActivityRepository activities;PricingService service;UUID id=UUID.randomUUID();TrainingCase c;TrainingPricing p;@BeforeEach void setup(){MockitoAnnotations.openMocks(this);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(UUID.randomUUID().toString(),null));service=new PricingService(pricings,cases,programs,activities);c=mock(TrainingCase.class);when(c.getStatus()).thenReturn(TrainingCaseStatus.TARIFICATION_EN_PREPARATION);when(cases.locked(id)).thenReturn(Optional.of(c));p=new TrainingPricing(id);p.insert();p.setTrainerCost(new BigDecimal("100"));when(pricings.locked(id)).thenReturn(Optional.of(p));}@AfterEach void clear(){SecurityContextHolder.clearContext();}@Test void calculatesMarginVatAndTtcWithThreeDecimals(){PricingResponse r=service.update(id,new PricingRequest(null,new BigDecimal("20"),null,null,null,new BigDecimal("10"),new BigDecimal("19"),null,null));assertThat(r.totalCosts()).isEqualByComparingTo("120.000");assertThat(r.marginAmount()).isEqualByComparingTo("12.000");assertThat(r.totalExcludingTax()).isEqualByComparingTo("132.000");assertThat(r.vatAmount()).isEqualByComparingTo("25.080");assertThat(r.totalIncludingTax()).isEqualByComparingTo("157.080");}@Test void zeroVatRequiresJustification(){assertThatThrownBy(()->service.update(id,new PricingRequest(null,null,null,null,null,null,BigDecimal.ZERO,null,null))).isInstanceOf(ApiError.class).extracting("code").isEqualTo("VAT_EXEMPTION_JUSTIFICATION_REQUIRED");}}
